          }
        >
          <Stack>
            <Select
              name="coverFit"
              label="Fit"
              value={fit}
              options={[
                { label: 'Contain', value: 'contain', description: 'Letterbox the cover' },
                { label: 'Cover', value: 'cover' },
              ]}
              searchable={false}
              clearable={false}
              onChange={setFit}
            />
            <Select
              name="seriesName"
              label="Series"
              value={series}
              options={seriesNames}
              loading={loading}
              allowCreate
              onChange={setSeries}
            />
            {saved !== null && <Text tone="success">Saved: {saved}</Text>}
          </Stack>
        </Card>
      </Stack>
    </Page>
  );
}

